        long MOD = 1_000_000_007L;
        java.util.List<Integer> masks = new java.util.ArrayList<>();
        int ones = 0;
        for (int x : nums) {
            if (x == 1) {
                ones++;
                continue;
            }
            int mask = 0;
            boolean valid = true;
            for (int i = 0; i < 10; i++) {
                int p = primes[i];
                if (x % (p * p) == 0) {
                    valid = false;
                    break;
                }
                if (x % p == 0) {
                    mask |= (1 << i);
                }
            }
            if (valid) masks.add(mask);
        }
        long[] dp = new long[1 << 10];
        dp[0] = 1;
        for (int mask : masks) {
            for (int state = (1 << 10) - 1; state >= 0; state--) {
                if ((state & mask) == 0 && dp[state] > 0) {
                    dp[state | mask] = (dp[state | mask] + dp[state]) % MOD;
                }
            }
        }
        long total = 0;
        for (int state = 0; state < (1 << 10); state++) {
            total = (total + dp[state]) % MOD;
        }
        long p2 = 1;
        for (int i = 0; i < ones; i++) {
            p2 = (p2 * 2) % MOD;
        }
        return (int) ((total * p2 - 1 + MOD) % MOD);
    }
